package edu.hfut.aggregate.controller;
import java.util.*;import org.springframework.web.bind.annotation.*;import org.springframework.cloud.netflix.ribbon.SpringClientFactory;import org.springframework.cloud.client.loadbalancer.LoadBalancerClient;import com.netflix.loadbalancer.*;import com.netflix.hystrix.*;import static edu.hfut.aggregate.dto.Views.map;
@RestController public class ComponentsController{
 private final SpringClientFactory f;private final LoadBalancerClient c;public ComponentsController(SpringClientFactory f,LoadBalancerClient c){this.f=f;this.c=c;}
 @GetMapping("/internal/components")public Object components(){Map<String,Object>lbs=new LinkedHashMap<>();for(String n:Arrays.asList("user-service","appointment-service","access-service","exception-service","campus-gateway")){ILoadBalancer b=f.getLoadBalancer(n);lbs.put(n,map("implementation",b.getClass().getName(),"servers",b.getAllServers().toString(),"rule",f.getInstance(n,IRule.class).getClass().getName()));}Map<String,Object>hits=new LinkedHashMap<>();for(String n:Arrays.asList("user-service","exception-service")){ILoadBalancer b=f.getLoadBalancer(n);Map<String,Object>h=new LinkedHashMap<>();for(Server server:b.getAllServers())h.put(String.valueOf(server.getPort()),((BaseLoadBalancer)b).getLoadBalancerStats().getSingleServerStat(server).getTotalRequestsCount());hits.put(n,h);}List<Object>circuits=new ArrayList<>();for(HystrixCommandMetrics m:HystrixCommandMetrics.getInstances()){HystrixCircuitBreaker b=HystrixCircuitBreaker.Factory.getInstance(m.getCommandKey());circuits.add(map("command",m.getCommandKey().name(),"open",b!=null&&b.isOpen(),"requests",m.getHealthCounts().getTotalRequests(),"errors",m.getHealthCounts().getErrorCount(),"failures",m.getCumulativeCount(HystrixEventType.FAILURE),"shortCircuits",m.getCumulativeCount(HystrixEventType.SHORT_CIRCUITED),"successes",m.getCumulativeCount(HystrixEventType.SUCCESS)));}return map("client",c.getClass().getName(),"loadBalancers",lbs,"ribbonRequestsByPort",hits,"circuits",circuits);}
}
